const stripNonProse = (input: string): string =>
  input
    .replace(/`[^`]*`/g, " ")
    .replace(/\[[^\]]*\]\([^)]*\)/g, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/[^A-Za-z]+/g, " ")
    .trim();

