  if (lines[0] !== "---") return null;
  let end = 1;
  while (end < lines.length && lines[end] !== "---") end += 1;
  if (end >= lines.length) return null;
  return {
    segment: { kind: "preserve", text: lines.slice(0, end + 1).join("\n") },
    nextIndex: end + 1,
  };
};

