const scanFence = (lines: string[], start: number): number => {
  let index = start + 1;
  while (index < lines.length && !FENCE.test(lines[index])) index += 1;
  if (index < lines.length) index += 1; // include the closing fence
  return index;
};

/** Index just past a run of blank lines starting at `start`. */
const scanBlankRun = (lines: string[], start: number): number => {
  let index = start;
  while (index < lines.length && lines[index].trim() === "") index += 1;
  return index;
};

/** Split markdown into ordered, lossless segments. */
export function segmentMarkdown(md: string, options: { scope?: string } = {}): Segment[] {
  const lines = md.split("\n");
  const segments: Segment[] = [];
  let index = 0;

  const frontmatter = takeFrontmatter(lines);
  if (frontmatter) {
    segments.push(frontmatter.segment);
    index = frontmatter.nextIndex;
  }

  let block: string[] = [];
  const flush = (): void => {
    if (block.length > 0) {
      const segment = classifyBlock(block);
      if (segment.kind === "callout" || (segment.kind === "prose" && segment.generatedValues))
        segment.scope = options.scope;
      segments.push(segment);
      block = [];
    }
  };

  while (index < lines.length) {
    const line = lines[index];

    if (FENCE.test(line)) {
      flush();
      const start = index;
      index = scanFence(lines, start);
      const hasClosingFence = index > start + 1 && FENCE.test(lines[index - 1]);
      let previous = start - 1;
      while (previous >= 0 && lines[previous].trim() === "") previous -= 1;
      const metadata =
        previous >= 0 && isFlagOnly(lines[previous].trim()) ? `${lines[previous]}\n` : "";
      const audience = resolveExampleTargets([metadata + lines.slice(start, index).join("\n")]);
      const auditOnly = audience.automatica11y.length > 0 && audience.docs.length === 0;
      if (HTML_FENCE.test(line) && hasClosingFence && !auditOnly) {
        segments.push({
          kind: "html",
          opening: lines[start],
          body: segmentDemoHtml(lines.slice(start + 1, index - 1).join("\n")),
          closing: lines[index - 1],
        });
      } else if (PROMPT_FENCE.test(line) && hasClosingFence) {
        segments.push({
          kind: "prompt",
          opening: lines[start],
          body: lines.slice(start + 1, index - 1).join("\n"),
          closing: lines[index - 1],
        });
      } else {
        segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
      }
      continue;
    }

    if (line.trim() === "") {
      flush();
      const start = index;
      index = scanBlankRun(lines, start);
      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
      continue;
    }

    if (isFlagOnly(line.trim())) {
      flush();
      segments.push({ kind: "preserve", text: line });
      index += 1;
      continue;
    }

    block.push(line);
    index += 1;
  }
  flush();

  return segments;
}

/** Translatable header labels + Description-cell units from one table segment, in document order. */
const collectTableUnits = (segment: Extract<Segment, { kind: "table" }>): TranslatableUnit[] => {
  const units: TranslatableUnit[] = [];
  for (const header of segment.rows[segment.headerRow]) {
    if (header !== "") units.push({ text: header, kind: "glossary" });
  }
  for (let row = 0; row < segment.rows.length; row += 1) {
    if (row === segment.headerRow || row === segment.separatorRow) continue;
    for (const col of segment.descCols) {
      const cell = segment.rows[row][col];
      if (cell !== undefined && isTranslatableCell(cell)) {
        units.push({ text: cell, kind: cellKind(cell) });
      }
    }
  }
  return units;
};

/** Every translatable unit across the segments, in document order (callers dedupe by content). */
export function collectUnits(segments: readonly Segment[]): TranslatableUnit[] {
  const units: TranslatableUnit[] = [];
  for (const segment of segments) {
    if (segment.kind === "glossary" || segment.kind === "prose") {
      units.push({
        text:
          segment.kind === "prose" && segment.generatedValues
            ? scopeGeneratedMarkdown(generatedMarkdown(segment.text), segment.scope).template
            : segment.text,
        kind: segment.kind,
      });
      continue;
    }
    if (segment.kind === "prompt") {
      units.push({ text: segment.body, kind: "prose" });
      continue;
    }
    if (segment.kind === "html") {
      units.push(
        ...collectDemoUnits(segment.body).map((text) => ({
          text,
          kind: "prose" as const,
          translateCodeShaped: true,
        })),
      );
      continue;
    }
    if (segment.kind === "table") {
      units.push(...collectTableUnits(segment));
      continue;
    }
    if (segment.kind === "audit") {
      units.push(
        ...collectDemoUnits(segment.body).map((text) => ({ text, kind: "prose" as const })),
      );
      continue;
    }
    if (segment.kind === "callout") {
      units.push(
        { text: segment.label, kind: "glossary" },
        {
          text: scopeGeneratedMarkdown(generatedMarkdown(segment.note), segment.scope).template,
          kind: "prose",
        },
      );
    }
  }
  return units;
}

/** Rebuild markdown from segments, resolving each translatable unit through `resolve`. */
export function reassemble(segments: readonly Segment[], resolve: Resolve): string {
  return segments.map((segment) => renderSegment(segment, resolve)).join("\n");
}

const resolveGenerated = (text: string, resolve: Resolve, scope?: string): string => {
  const generated = scopeGeneratedMarkdown(generatedMarkdown(text), scope);
  return restoreGeneratedMarkdown(resolve(generated.template, "prose"), generated);
};

const renderSegment = (segment: Segment, resolve: Resolve): string => {
  switch (segment.kind) {
    case "preserve":
      return segment.text;
    case "prompt":
      return [segment.opening, resolve(segment.body, "prose"), segment.closing].join("\n");
    case "html":
      return [
        segment.opening,
        reassembleDemoHtml(segment.body, (text) => resolve(text, "prose")),
        segment.closing,
      ].join("\n");
    case "audit":
      return reassembleDemoHtml(segment.body, (text) => resolve(text, "prose"));
    case "glossary":
      return resolve(segment.text, segment.kind);
    case "prose":
      return segment.generatedValues
        ? `${GENERATED_VALUES_MARKER}\n${resolveGenerated(segment.text, resolve, segment.scope)}`
        : resolve(segment.text, segment.kind);
    case "table":
      return renderTable(segment, resolve);
    case "callout":
      return [
        segment.marker,
        segment.alertLine,
        `> **${resolve(segment.label, "glossary")}** — ${resolveGenerated(segment.note, resolve, segment.scope)}`,
      ].join("\n");
  }
};

const renderTable = (segment: Extract<Segment, { kind: "table" }>, resolve: Resolve): string =>
  segment.rows
    .map((cells, row) => {
      const rendered = cells.map((cell, col) => {
        if (row === segment.separatorRow) return cell;
        if (row === segment.headerRow) return cell === "" ? cell : resolve(cell, "glossary");
        if (segment.descCols.includes(col) && isTranslatableCell(cell)) {
          return resolve(cell, cellKind(cell));
        }
        return cell;
      });
      return rebuildRow(rendered);
    })
    .join("\n");

