const find = (segments: Segment[], needle: string): Segment => {
  const match = segments.filter(
    (s) =>
      s.kind !== "table" &&
      s.kind !== "callout" &&
      s.kind !== "prompt" &&
      s.kind !== "html" &&
      s.kind !== "audit" &&
      s.text.includes(needle),
  );
  expect(match.length, `exactly one segment contains ${JSON.stringify(needle)}`).toBe(1);
  return match[0];
};

