    expect(texts).toContain("An AI action."); // description cell → prose
    expect(texts).toContain("A destructive action.");
    expect(texts).not.toContain("`.-color-ai`"); // code column, never translated
    expect(texts).not.toContain("—"); // empty description cell, skipped
    const proseTexts = units.filter((u) => u.kind === "prose").map((u) => u.text);
    expect(proseTexts).toEqual(["An AI action.", "A destructive action."]);
  });

  test("reassembly translates header + Description cells only, keeping code + structure", () => {
    const resolve = (text: string, kind: TranslationKind): string =>
      kind === "prose" ? `HU(${text})` : `[${text}]`;
    const out = renderOne(modifiers, resolve);
    expect(out).toBe(
      [
        "| [Modifier] | [Description] |",
        "| --- | --- |",
        "| `.-color-ai` | HU(An AI action.) |",
        "| `.-color-danger` | HU(A destructive action.) |",
        "| `.-size-lg` | — |",
      ].join("\n"),
    );
  });

  test("a table with an escaped pipe round-trips exactly", () => {
    const out = renderOne(tokens, identity);
    expect(out).toBe(
      [
        "| Token | Type | Value |",
        "| --- | --- | --- |",
        "| `--instui-font-family-base` | `[ <font-family-name> \\| <generic-font-family> ]#` | `Arial` |",
      ].join("\n"),
    );
  });

  test("a table that can't rebuild exactly falls back to preserve", () => {
    // Ragged padding the rebuilder would normalize → preserved whole instead of reformatted.
    const ragged = ["|A|B|", "| --- | --- |", "|  x  |  y  |"].join("\n");
    const segments = segmentMarkdown(ragged);
    expect(segments.some((s) => s.kind === "table")).toBe(false);
    expect(reassemble(segments, identity)).toBe(ragged);
  });

  test("preserves original table spacing when translating cells", () => {
    // Wide-spaced table like docs/compatibility.md: spacing should be preserved even after translating cells
    const wideSpaced = [
      "| Package | Description |",
      "| --- | --- |",
      "| `@instructure/ui-icons` | Some icons package |",
    ].join("\n");
    const segments = segmentMarkdown(wideSpaced);
    const tableSegment = segments.find((s) => s.kind === "table");
    expect(tableSegment?.kind).toBe("table");

    // Translate with a function that changes cell content
    const resolve = (text: string, kind: TranslationKind): string =>
      text.includes("icons") ? "TRANSLATED_ICONS" : text;
    const out = reassemble([tableSegment!], resolve);

    // Spacing should match the input, not be normalized to minimal
    expect(out).toBe(
      [
        "| Package | Description |",
        "| --- | --- |",
        "| `@instructure/ui-icons` | TRANSLATED_ICONS |",
      ].join("\n"),
    );
  });
});

/** Reassemble a single segment in isolation (no inter-segment newline joins). */
function renderOne(segment: Segment, resolve: (t: string, k: TranslationKind) => string): string {
  return reassemble([segment], resolve);
}

describe("accessibility audit tables", () => {
  const table = [
    "<!-- accessibility-audit:start -->",
    '<table class="pantoken-a11y-table">',
    '<tr><th scope="row"><span class="pantoken-a11y-check">color-contrast</span></th><td><span class="instui-pill pantoken-doc-tag">Fail</span></td></tr>',
    "<tr><td><p><strong>Rebrand (light):</strong> Text <code>.-color-ai</code> is too faint.</p></td></tr>",
    "</table>",
    "<!-- accessibility-audit:end -->",
  ].join("\n");

  test("translates visible text, not markup or code", () => {
    const segments = segmentMarkdown(table);
    expect(segments.map((segment) => segment.kind)).toEqual(["audit"]);
    const texts = collectUnits(segments).map((unit) => unit.text);
    expect(texts).toContain("Fail");
    expect(texts).toContain(" Text ");
    expect(texts).not.toContain(".-color-ai");
    const out = reassemble(segments, (text) => (text === "Fail" ? "Hiba" : text));
    expect(out).toContain(">Hiba</span>");
    expect(out.replace("Hiba", "Fail")).toBe(table);
  });
});

